/**
 * Retail signals every QualificationContext starts with, so a cold session still
 * evaluates the audience condition trees sensibly (e.g. a `cart_adds eq 0` predicate
 * must be true for a brand-new shopper). Numeric counters initialize to 0.
 * Exported for the ShopperReflex DO (doc 16 §6, P2) — both hosts qualify against
 * the identical baseline.
 */
export const RETAIL_SIGNAL_DEFAULTS: Record<string, number> = {
  product_views: 0,
  cart_adds: 0,
  wishlist_adds: 0,
  page_views: 0,
  category_dwell_ms: 0,
  // `purchases eq 0` gates the ready-to-buy/cart audiences — without a default an
  // anonymous session evaluates undefined === 0 → false, and they can NEVER qualify.
  purchases: 0,
};

// ─────────────────────────────────────────────────────────────────────────────
// P2 seam (doc 16 §6): the pure/pipeline pieces of this engine that the
// ShopperReflex Durable Object must run IDENTICALLY are lifted to module scope
// and exported. The class methods below delegate to these — same behavior, one
// source, two hosts (request path today, per-shopper DO behind REFLEX_HOST='do').
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Update attributes based on a retail action event. Retail intent can arrive either
 * as a typed event or carried in `event.data.action` (the storefront posts catalog
 * events as page_view/custom with a `line`/`productId`/`action` payload), so we
 * inspect both. Derives the attributes the Coach audiences are written against:
 * viewed_product_line, product_views, cart_adds, wishlist_adds, price_band_viewed,
 * category_dwell_ms, page_views.
 */
export function applyEventToAttributes(
  attributes: Record<string, any>,
  event: ActionEvent,
  catalog: CatalogService
): void {
  const data = event.data ?? {};
  // The retail action: explicit data.action wins, else the event type.
  const action = actionOf(event);

  const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);
  const inc = (key: string, by = 1) => {
    attributes[key] = num(attributes[key]) + by;
  };

  // Resolve a product (if referenced) so we can enrich line / price band from the catalog.
  const productId: string | undefined = data.productId ?? data.product_id ?? data.sku;
  const product = productId ? catalog.getProduct(productId) : undefined;
  const line: string | undefined =
    product?.line ?? (typeof data.line === 'string' ? data.line : undefined);
  const priceUsd: number | undefined =
    product?.price_usd ?? (typeof data.price_usd === 'number' ? data.price_usd : undefined);

  const applyLineAndBand = () => {
    if (line) attributes.viewed_product_line = line;
    if (typeof priceUsd === 'number') attributes.price_band_viewed = priceBandOf(priceUsd);
  };

  switch (action) {
    case 'product_view':
    case 'pdp_view':
    case 'view_product':
      inc('product_views');
      applyLineAndBand();
      if (typeof data.dwellMs === 'number') inc('category_dwell_ms', data.dwellMs);
      break;

    case 'add_to_cart':
    case 'cart_add':
      inc('cart_adds');
      applyLineAndBand();
      break;

    case 'wishlist':
    case 'wishlist_add':
    case 'add_to_wishlist':
    case 'save_for_later':
      inc('wishlist_adds');
      applyLineAndBand();
      break;

    case 'purchase':
    case 'checkout':
    case 'order_complete':
      inc('purchases');
      applyLineAndBand();
      break;

    case 'page_view':
      inc('page_views');
      if (typeof data.path === 'string') attributes.last_page_path = data.path;
      if (typeof data.dwellMs === 'number') inc('category_dwell_ms', data.dwellMs);
      // A page_view that carries a product line/category still updates affinity.
      applyLineAndBand();
      break;

    case 'button_click':
      inc('button_clicks');
      if (data.buttonId) attributes.last_button_clicked = data.buttonId;
      break;

    default:
      // Unknown/custom retail signal: still capture line/band if present so affinity grows.
      applyLineAndBand();
      if (typeof data.dwellMs === 'number') inc('category_dwell_ms', data.dwellMs);
      break;
  }

  attributes.last_activity = Date.now();
}

/**
 * Catalog-aware engagement score. Weights real retail intent: cart adds and
 * wishlist saves dominate, PDP views and dwell contribute, page views are a light
 * signal. Clamped to 0–100 so it stays a stable, comparable session score.
 */
export function calculateEngagementScore(attributes: Record<string, any>): number {
  const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);

  const productViews = num(attributes.product_views);
  const cartAdds = num(attributes.cart_adds);
  const wishlistAdds = num(attributes.wishlist_adds);
  const purchases = num(attributes.purchases);
  const pageViews = num(attributes.page_views);
  const dwellMinutes = num(attributes.category_dwell_ms) / 60000;

  const score =
    productViews * 8 +
    cartAdds * 25 +
    wishlistAdds * 15 +
    purchases * 40 +
    pageViews * 2 +
    dwellMinutes * 5;

  return Math.min(100, Math.round(score));
}

/** Set-diff over segment keys — the change-detect both hosts trigger pushes on. */
export function hasSegmentChanges(oldSegments: string[], newSegments: string[]): boolean {
  if (oldSegments.length !== newSegments.length) {
    return true;
  }
  const oldSet = new Set(oldSegments);
  return newSegments.some((segment) => !oldSet.has(segment));
}

/**
 * Idempotently load the Coach launch audiences + the catalog-generated affinity
 * audiences (doc 16 §5) into the shared AudienceStore. Version-gated on a hash of
 * the generated set so the hot path pays ONE KV read; the diff
 * (regenerateCatalogAudiences) runs only when the catalog or generator config
 * actually changed — and never clobbers pinned/human edits.
 *
 * Multi-surface (PH build spec §3): each surface owns its OWN version marker and
 * its own archive scope, so two demos regenerating over one store cannot archive
 * each other's audiences on alternating passes. The Coach launch seeds belong to
 * the default surface and are seeded only on its pass.
 */
export async function ensureAudiencesSeeded(
  env: Env,
  catalogService: CatalogService,
  surface: DemoSurface = DEFAULT_SURFACE,
  tenant: TenantId = DEFAULT_TENANT
): Promise<void> {
  const store = new KvAudienceStore(env, tenant);
  if (surface === DEFAULT_SURFACE) await store.seed(SEED_AUDIENCES);
  const generated = generateAffinityAudiences(
    catalogService.getAllProducts() as unknown as Array<Record<string, unknown>>,
    await resolveReflexConfig(env, surface),
    surface === DEFAULT_SURFACE
      ? DEFAULT_GENERATOR_CONFIG
      : { ...DEFAULT_GENERATOR_CONFIG, surface, keyPrefix: audienceKeyPrefixFor(surface) }
  );
  const setHash = generated.map((d) => `${d.key}:${d.generatorHash}`).join('|');
  const MARKER = audgenMarkerFor(surface);
  if ((await new TenantKV(env.CACHE as unknown as KVLike, tenant).get(MARKER)) === setHash) return;
  const s = await regenerateCatalogAudiences(store, generated, surface);
  await new TenantKV(env.CACHE as unknown as KVLike, tenant).put(MARKER, setHash);
  console.log(
    `[reflex] catalog audiences regenerated: +${s.published.length} ~${s.updated.length} −${s.archived.length}` +
      ` (skipped: ${s.skippedHumanEdited.length} human-edited, ${s.skippedPinned.length} pinned)`
  );
}

export class RealtimeSegmentEngine {
  readonly tenant: TenantId;
  private readonly cache: KVLike;
  private readonly sessions: KVLike;
  /**
   * CW6: how background work outlives the response. The route hands in its
   * execution context per call; without one (tests), a promise is simply let go.
   */
  private keepAlive?: (p: Promise<unknown>) => void;

  private env: Env;
  private principal?: SessionCapability;
  private connectors: Connectors;
  private sessionManager: SessionManager;
  private featureVariableManager: FeatureVariableManager;
  private catalogService: CatalogService;
  /** Audiences are seeded once per engine instance PER SURFACE (idempotent on the
      store regardless). */
  private seeded = new Set<DemoSurface>();

  constructor(
    env: Env,
    connectors?: Connectors,
    options?: { domain?: string; secure?: boolean; tenant?: TenantId; principal?: SessionCapability }
  ) {
    this.env = env;
    this.principal = options?.principal;
    // The brand this engine decides for. Flows straight through to SessionManager
    // via `options`; the audience store and the socket name need it explicitly.
    this.tenant = options?.tenant ?? DEFAULT_TENANT;
    // Default to getConnectors(env) so existing single-arg route calls keep working
    // while the spec's two-arg `new RealtimeSegmentEngine(env, getConnectors(env))` is honored.
    this.connectors = connectors ?? getConnectors(env);
    this.sessionManager = new SessionManager(env, options);
    this.featureVariableManager = new FeatureVariableManager(env, this.tenant);
    // The two raw stores this class still touched directly, now scoped like
    // everything that goes through SessionManager and the audience store.
    this.cache = new TenantKV(env.CACHE as unknown as KVLike, this.tenant);
    this.sessions = new TenantKV(env.SESSIONS as unknown as KVLike, this.tenant);
    this.catalogService = new CatalogService();
  }

  /**
   * Idempotently load the Coach launch audiences into the shared AudienceStore.
   * Called at the start of any operation that qualifies segments, so ODP (mock or
   * live) always has the seed audiences plus any Opal-created ones to evaluate.
   * Delegates to the exported ensureAudiencesSeeded (shared with the P2 DO).
   */
  private async ensureSeeded(surface: DemoSurface = DEFAULT_SURFACE): Promise<void> {
    if (this.seeded.has(surface)) return;
    try {
      await ensureAudiencesSeeded(this.env, await this.catalogFor(surface), surface);
      this.seeded.add(surface);
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error seeding audiences');
    }
  }

  /** The surface an event belongs to — explicit field, else `source`, else coach. */
  private surfaceOf(event: ActionEvent): DemoSurface {
    return resolveSurface({
      source: event.source,
      surface: event.surface ?? (event.data as Record<string, unknown> | undefined)?.surface as string | undefined,
    });
  }

  /**
   * The catalog this surface scores against. The default surface keeps the
   * instance built in the constructor — same object, same graph, same order — so
   * nothing about the retail path moves; other surfaces resolve a memoized
   * per-surface CatalogService from the registry.
   */
  private async catalogFor(surface: DemoSurface): Promise<CatalogService> {
    return surface === DEFAULT_SURFACE ? this.catalogService : catalogServiceFor(surface);
  }

  async processActionEvent(event: ActionEvent, sessionId?: string): Promise<PersonalizationUpdate | null> {
    if (this.principal) {
      assertSessionTarget(this.principal, event.userId, sessionId);
      sessionId = this.principal.sessionId;
      await this.sessionManager.getSession(sessionId);
    }
    try {
      // 0. Resolve the demo surface this event belongs to, then seed THAT surface's
      // audiences idempotently (cold sessions qualify on first event). Everything
      // below reads the surface's catalog + reflex config; 'coach' resolves to the
      // exact objects this method used before the multi-surface split.
      const surface = this.surfaceOf(event);
      const catalogService = await this.catalogFor(surface);
      const reflexConfig = await resolveReflexConfig(this.env, surface);
      const audiencePrefix = audienceKeyPrefixFor(surface);
      await this.ensureSeeded(surface);

      // 1. Get or create session
      const currentSessionId = sessionId || this.sessionManager.generateSessionId();
      let sessionData = await this.sessionManager.getSession(currentSessionId);

      // If no session exists, get user profile data from legacy method
      if (!sessionData) {
        const userProfile = await this.getUserProfile(event.userId);
        sessionData = await this.sessionManager.createOrUpdateSession(currentSessionId, event.userId, {
          anonymousId: event.anonymousId,
          segments: userProfile.segments,
          attributes: userProfile.attributes,
          metadata: {
            firstSeen: userProfile.metadata.firstSeen,
            lastSeen: Date.now(),
            sessionCount: userProfile.metadata.sessionCount,
            engagementScore: calculateEngagementScore(userProfile.attributes),
            lastSegmentUpdate: userProfile.lastUpdated
          },
          preferences: {
            trackingConsent: true,
            personalizationEnabled: true,
            cookieConsent: true
          }
        }, event.entry);
      }

      // 2. Apply this event's retail signals to a fresh attribute snapshot.
      const newAttributes = { ...sessionData.attributes };
      applyEventToAttributes(newAttributes, event, catalogService);
      const newEngagementScore = calculateEngagementScore(newAttributes);

      // 2.5 Edge Affinity Reflex (doc 16): decayed per-dimension affinity via the
      // pure core. State rides the session in P0 (relocates into the DO in P2).
      // The ENGINE clock is authoritative — client timestamps are advisory only.
      const nowMs = Date.now();
      const reflexOn = (this.env.REFLEX_ENABLED ?? 'true') !== 'false';
      let reflex: ReflexResult | null = null;
      if (reflexOn) {
        const data = event.data ?? {};
        const pid = data.productId ?? data.product_id ?? data.sku;
        const product = pid ? catalogService.getProduct(String(pid)) : undefined;
        const action = actionOf(event);
        reflex = applyReflex(
          sessionData.reflex,
          {
            action,
            // A held product's attributes, or, where the scope allows it, the
            // event's own (CW24): a customer's site scores against their catalog.
            touches: isContentAction(action)
              ? contentTouches(data as Record<string, unknown>, reflexConfig)
              : touchesForEvent(data as Record<string, unknown>, product as unknown as Record<string, unknown> | undefined, reflexConfig),
          },
          nowMs,
          reflexConfig
        );
        // CW6: the same touches, fanned into the shopper's region as a population count.
        (this.keepAlive ?? ((p: Promise<unknown>) => { void p; }))(fanInRegionTrend(this.env, {
          tenant: surface, geo: event.geo, now: nowMs,
          touches: touchesForEvent(data as Record<string, unknown>, product as unknown as Record<string, unknown> | undefined, reflexConfig),
          w: reflexConfig.weights[action] ?? 0,
        }));
      }

      // 3. Qualify segments through the ODP seam against the live context.
      const ctx = this.buildQualificationContext(
        event.userId,
        event.anonymousId ?? sessionData.anonymousId,
        newAttributes,
        sessionData.segments
      );
      ctx.surface = surface; // qualification evaluates only THIS surface's audiences
      const journeyStage = deriveStage(ctx);
      ctx.attributes.journey_stage = journeyStage; // stage is itself an audience attribute
      // Reflex scores are computed FRESH into the context (never persisted — they
      // decay by construction), so store-published affinity audiences can gte them.
      if (reflex) Object.assign(ctx.attributes, reflexAttributes(reflex.state, nowMs, reflexConfig));
      const localSegments = await this.connectors.segments.fetchQualifiedSegments(event.userId, ctx);
      // ODP loop (doc 16 §8): seed/refresh the session's LIVE ODP-qualified audiences.
      // Additive + hard-capped (1.5s in fetchOdpAudiences) — ODP can only ever ADD;
      // slow or down degrades to exactly the pre-ODP behavior.
      let odpSeed = sessionData.odpSeed ?? [];
      let odpSeedAt = sessionData.odpSeedAt ?? 0;
      let odpRing = Array.isArray(sessionData.odpRecentEvents) ? sessionData.odpRecentEvents.slice() : [];
      if (odpEnabled(this.env)) {
        // Ring maintenance + seed read policy live in odpLoop (updateOdpRing /
        // refreshOdpSeedIfDue) — shared verbatim with the ShopperReflex DO (P2)
        // so the two hosts can never drift.
        odpRing = updateOdpRing(odpRing, event, nowMs);
        const membershipChanged = !!reflex && (reflex.changes.entered.length > 0 || reflex.changes.exited.length > 0);
        ({ seed: odpSeed, seedAt: odpSeedAt } = await refreshOdpSeedIfDue(
          this.env,
          // event.userId is the stable first-party visitor id the client mints
          // and persists; the session id is only the fallback for a client that
          // does not send one.
          { visitorId: event.userId, sessionId: currentSessionId },
          odpRing,
          { seed: odpSeed, seedAt: odpSeedAt },
          nowMs,
          membershipChanged
        ));
      }
      // Union: local evaluation ∪ live reflex memberships ∪ ODP-confirmed seed —
      // any enter/exit drives the same change-detect → persist → decide → push loop.
      // The reflex core names memberships from the catalog alone; the surface
      // namespace is applied HERE so they match the generated audience keys
      // (prefix '' for coach ⇒ the same array, untouched).
      const reflexAudiences = reflex
        ? audiencePrefix
          ? reflex.state.audiences.map((k) => audiencePrefix + k)
          : reflex.state.audiences
        : [];
      const newSegments = Array.from(new Set([
        ...localSegments,
        ...reflexAudiences,
        ...odpSeed,
      ]));

      // 4. Detect what actually changed (segments OR journey stage) — either is a trigger.
      const segmentsChanged = hasSegmentChanges(sessionData.segments, newSegments);
      const stageChanged = sessionData.metadata.journeyStage !== journeyStage;

      if (!segmentsChanged && !stageChanged) {
        // No personalization change — persist the accrued attributes/activity and stop.
        await this.sessionManager.createOrUpdateSession(currentSessionId, event.userId, {
          ...sessionData,
          attributes: newAttributes,
          surface,
          reflex: reflex ? reflex.state : sessionData.reflex,
          odpSeed,
          odpSeedAt,
          odpRecentEvents: odpRing,
          metadata: {
            ...sessionData.metadata,
            lastSeen: Date.now(),
            engagementScore: newEngagementScore,
            journeyStage
          }
        }, event.entry);
        return null;
      }

      // 5. Persist new attributes, segments, engagement score, and journey stage.
      await this.sessionManager.createOrUpdateSession(currentSessionId, event.userId, {
        ...sessionData,
        attributes: newAttributes,
        surface,
        reflex: reflex ? reflex.state : sessionData.reflex,
        odpSeed,
        odpSeedAt,
        odpRecentEvents: odpRing,
        segments: newSegments,
        metadata: {
          ...sessionData.metadata,
          lastSeen: Date.now(),
          engagementScore: newEngagementScore,
          lastSegmentUpdate: Date.now(),
          journeyStage
        }
      }, event.entry);

      const updatedSessionData = await this.sessionManager.getSession(currentSessionId);
      if (!updatedSessionData) {
        throw new Error('Failed to update session data');
      }

      // 6. Decide the storefront modules through the Optimizely FX seam.
      const personalizationConfig = await this.getPersonalizationConfig(updatedSessionData, currentSessionId);

      // 7. Create the personalization update with retail payloads.
      const update: PersonalizationUpdate = {
        type: 'personalization_update',
        userId: event.userId,
        data: {
          segments: newSegments,
          decisions: personalizationConfig.decisions,
          featureVariables: personalizationConfig.featureVariables,
          recommendations: personalizationConfig.recommendations,
          sortOrder: personalizationConfig.sortOrder,
          journeyStage,
          // Live affinity payload for the Affinity Instrument (dims use original
          // catalog value names; changed = this event's explain records).
          affinity: reflex
            ? { ...reflexSnapshot(reflex.state, nowMs, reflexConfig), changed: reflex.changes.explain, odpConfirmed: odpSeed }
            : undefined,
          cookies: personalizationConfig.cookieUpdates,
          cookieHeaders: personalizationConfig.cookieHeaders,
          sessionId: currentSessionId,
          engagementScore: newEngagementScore,
          timestamp: Date.now(),
          source: event.source
        } as PersonalizationUpdate['data']
      };

      // 8. Broadcast update via WebSocket
      await this.broadcastUpdate(update);

      return update;

    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error processing action event');
      throw error;
    }
  }

  async getUserProfile(userId: string): Promise<UserProfile> {
    if (this.principal) {
      assertSessionTarget(this.principal, userId);
      const data = await this.sessionManager.getSession(this.principal.sessionId);
      return {
        userId, segments: data?.segments ?? [], attributes: data?.attributes ?? {}, events: [], lastUpdated: data?.metadata.lastSegmentUpdate ?? Date.now(),
        metadata: { firstSeen: data?.metadata.firstSeen ?? Date.now(), lastSeen: data?.metadata.lastSeen ?? Date.now(), sessionCount: data?.metadata.sessionCount ?? 0, emailOpens: 0, formSubmissions: 0, pageViews: 0 },
      };
    }
    const cacheKey = `profile:${userId}`;
    const cached = await this.cache.get(cacheKey, 'json') as UserProfile;

    if (cached) {
      return cached;
    }

    // Create new profile — cold start: no segments yet (ODP qualifies on first event).
    return {
      userId,
      segments: [],
      attributes: {},
      lastUpdated: Date.now(),
      events: [],
      metadata: {
        firstSeen: Date.now(),
        lastSeen: Date.now(),
        sessionCount: 1,
        emailOpens: 0,
        formSubmissions: 0,
        pageViews: 0
      }
    };
  }

  async saveUserProfile(profile: UserProfile): Promise<void> {
    if (this.principal) {
      assertSessionTarget(this.principal, profile.userId);
      await this.sessionManager.getSession(this.principal.sessionId);
    }
    const cacheKey = `profile:${profile.userId}`;
    await this.cache.put(cacheKey, JSON.stringify(profile), {
      expirationTtl: 7 * 24 * 60 * 60 // 7 days
    });
  }

  /**
   * Build the real-time QualificationContext the SegmentProvider qualifies against.
   * Numeric retail signals are initialized to 0 so cold sessions evaluate condition
   * trees sensibly (e.g. `cart_adds eq 0` is true for a brand-new shopper).
   */
  private buildQualificationContext(
    userId: string,
    anonymousId: string | undefined,
    attributes: Record<string, any>,
    segments: string[]
  ): QualificationContext {
    return {
      userId,
      anonymousId,
      attributes: { ...RETAIL_SIGNAL_DEFAULTS, ...attributes },
      segments
    };
  }

  // updateAttributesWithEvent / hasSegmentChanges / calculateEngagementScore were
  // lifted verbatim to exported module functions (applyEventToAttributes, …) so
  // the ShopperReflex DO runs the identical pipeline — see the P2 seam block above.

  private async getPersonalizationConfig(sessionData: SessionData, sessionId: string): Promise<PersonalizationConfig> {
    // The session remembers which demo it belongs to (absent ⇒ coach), so the
    // config path resolves the same catalog/config the event path scored with.
    const surface = resolveSurface({ surface: sessionData.surface });
    const catalogService = await this.catalogFor(surface);
    const attributes = { ...RETAIL_SIGNAL_DEFAULTS, ...sessionData.attributes };
    // Live affinity reads for the decision layer (doc 16 §10 choreography):
    // computed FRESH from the reflex state — they decay by construction, so they
    // are never persisted; the decision sees the score as of THIS moment.
    if ((this.env.REFLEX_ENABLED ?? 'true') !== 'false' && sessionData.reflex) {
      Object.assign(
        attributes,
        reflexAttributes(sessionData.reflex, Date.now(), await resolveReflexConfig(this.env, surface))
      );
    }

    const visitNumber = sessionData.metadata.visitCount ?? 1;
    const userAttributes = {
      segments: sessionData.segments,
      ...attributes,
      engagement_score: sessionData.metadata.engagementScore,
      // session_count is the INTERACTION count and always has been. It is kept
      // because it is persisted and read elsewhere; it is not the visit number
      // and must never be used as one.
      session_count: sessionData.metadata.sessionCount,
      // The two dimensions Mandeep named, and levels 1 and 2 of doc 22's pooling
      // ladder. visit_bucket is the cut the learning statistics pool on; the raw
      // number rides along for anything that wants finer grain.
      visit_number: visitNumber,
      visit_bucket: visitBucket(visitNumber),
      entry_channel: sessionData.metadata.entryChannel ?? 'direct',
      journey_stage: sessionData.metadata.journeyStage,
      days_since_first_seen: Math.floor((Date.now() - sessionData.metadata.firstSeen) / (24 * 60 * 60 * 1000)),
      tracking_consent: sessionData.preferences.trackingConsent,
      personalization_enabled: sessionData.preferences.personalizationEnabled
    };

    const journeyStage: 'early' | 'mid' | 'late' = sessionData.metadata.journeyStage ?? 'early';

    // Decide the full storefront module set through the Optimizely FX seam.
    const decisions = await this.connectors.decisions.decideAll(
      CATALOG_FLAG_KEYS,
      sessionData.userId,
      sessionData.segments,
      userAttributes
    );

    // Flat views derived from decisions (back-compat with the existing route response shape).
    const featureVariables: Record<string, any> = {};
    const featureFlags: Record<string, boolean> = {};
    const experiments: Record<string, string> = {};
    for (const [flagKey, decision] of Object.entries(decisions)) {
      featureVariables[flagKey] = decision.variables;
      featureFlags[flagKey] = decision.enabled;
      if (decision.variationKey) experiments[flagKey] = decision.variationKey;
    }

    // Catalog-aware recommendations + personalized sort for this session.
    const anchorLine =
      typeof sessionData.attributes.viewed_product_line === 'string'
        ? sessionData.attributes.viewed_product_line
        : undefined;
    const recommendations = catalogService.getRecommendations(
      { line: anchorLine },
      sessionData.segments,
      8
    );
    const sortOrder = catalogService
      .sortForSegments(null, sessionData.segments, sessionData.attributes)
      .slice(0, 24)
      .map((p) => p.id);

    // Enhanced feature variables (unchanged — driven by FeatureVariableManager).
    const enhancedFeatureVariables = await this.featureVariableManager.getSessionFeatureVariables(sessionData);

    // Legacy cookie updates for backward compatibility.
    const cookieUpdates = this.generateCookieUpdates(sessionData.segments, attributes, journeyStage);

    // Enhanced secure cookies via SessionManager.
    const sessionCookies = this.sessionManager.generateSessionCookies(sessionData, sessionId);
    const cookieHeaders = this.sessionManager.createCookieHeaders(sessionCookies);

    return {
      decisions,
      featureFlags,
      experiments,
      featureVariables,
      enhancedFeatureVariables,
      cookieUpdates,
      cookieHeaders,
      segments: sessionData.segments,
      recommendations,
      sortOrder,
      journeyStage,
      sessionData
    };
  }

  private generateCookieUpdates(
    segments: string[],
    attributes: Record<string, any>,
    journeyStage: 'early' | 'mid' | 'late'
  ): Record<string, string> {
    return {
      'opt_segments': segments.join(','),
      'opt_last_update': Date.now().toString(),
      'opt_product_views': (attributes.product_views ?? 0).toString(),
      'opt_cart_adds': (attributes.cart_adds ?? 0).toString(),
      'opt_journey_stage': journeyStage,
      'opt_engagement_score': calculateEngagementScore(attributes).toString()
    };
  }

  private async broadcastUpdate(update: PersonalizationUpdate): Promise<void> {
    try {
      const id = this.env.PERSONALIZATION_WEBSOCKET.idFromName(shopperObjectName(this.tenant, update.userId));
      const websocketObject = this.env.PERSONALIZATION_WEBSOCKET.get(id);

      await websocketObject.fetch(new Request('http://fake/broadcast', {
        method: 'POST',
        body: JSON.stringify(update),
        headers: { 'Content-Type': 'application/json' }
      }));
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error broadcasting update');
    }
  }

  // Get user segments for external API calls
  async getUserSegments(userId: string): Promise<string[]> {
    // Prefer the live session context if one exists, so segments reflect accrued signals.
    const sessionData = await this.sessionManager.getSessionByUserId(userId);
    const surface = resolveSurface({ surface: sessionData?.surface });
    await this.ensureSeeded(surface);

    const attributes = sessionData?.attributes ?? {};
    const segments = sessionData?.segments ?? [];
    const ctx = this.buildQualificationContext(
      userId,
      sessionData?.anonymousId,
      attributes,
      segments
    );
    ctx.surface = surface;
    ctx.attributes.journey_stage = deriveStage(ctx);
    return this.connectors.segments.fetchQualifiedSegments(userId, ctx);
  }

  // Manual segment assignment (operator/admin path) — adds a segment to the profile and broadcasts.
  async assignSegment(userId: string, segment: string, source: string = 'manual'): Promise<void> {
    if (this.principal) {
      assertSessionTarget(this.principal, userId);
      await this.sessionManager.getSession(this.principal.sessionId);
    }
    const profile = await this.getUserProfile(userId);

    if (!profile.segments.includes(segment)) {
      profile.segments.push(segment);
      profile.lastUpdated = Date.now();
      await this.saveUserProfile(profile);

      // Mirror onto the live session if present, so subsequent decisions see it.
      const sessionData = await this.sessionManager.getSessionByUserId(userId);
      if (sessionData) {
        const merged = Array.from(new Set([...sessionData.segments, segment]));
        await this.sessionManager.updateUserSegments(
          await this.sessionIdForUser(userId),
          merged,
          sessionData.metadata.engagementScore
        );
      }

      // Broadcast update
      const update: PersonalizationUpdate = {
        type: 'segment_update',
        userId,
        data: {
          segments: profile.segments,
          timestamp: Date.now(),
          source
        }
      };

      await this.broadcastUpdate(update);
    }
  }

  /** Resolve the active sessionId for a user (used by manual segment assignment). */
  private async sessionIdForUser(userId: string): Promise<string> {
    if (this.principal) {
      assertSessionTarget(this.principal, userId);
      return this.principal.sessionId;
    }
    const sid = (await this.sessions.get(`user:${userId}`)) as string | null;
    return sid ?? this.sessionManager.generateSessionId();
  }

  // Session Management Methods for API integration

  /**
   * Create or get session from cookie header
   */
  async getOrCreateSessionFromCookies(
    cookieHeader: string | null,
    userId: string,
    /** CW37. Where the session write goes instead of the response path. See SessionManager. */
    defer?: (p: Promise<unknown>) => void,
    /**
     * CW39. The browsing session the CLIENT is already carrying. The SDK keeps
     * one with an idle rule and sends it on the snapshot and on every event, and
     * both the decision record and the outcome prefer it -- but nothing used it
     * to find or name the session, so two requests arriving together each made a
     * session of their own and one visit was counted as two. Used when the
     * cookie says nothing, which on the decision route is always: that route
     * sets no cookie.
     */
    clientSessionId?: string,
  ): Promise<{
    sessionId: string;
    sessionData: SessionData;
    isNewSession: boolean;
  }> {
    const cookies = this.sessionManager.parseSessionCookies(cookieHeader);
    if (this.principal) {
      assertSessionTarget(this.principal, userId, clientSessionId);
      const sessionId = this.principal.sessionId;
      const existing = await this.sessionManager.getSession(sessionId);
      if (existing) return { sessionId, sessionData: existing, isNewSession: false };
      // Fresh anonymous authority never restores a legacy profile or its mirrors.
      // Explicit cookie refusals may only restrict; they cannot enable tracking.
      const now = Date.now();
      const sessionData = await this.sessionManager.createOrUpdateSession(sessionId, userId, {
        segments: ['new_user'], attributes: {},
        metadata: { firstSeen: now, lastSeen: now, sessionCount: 0, engagementScore: 0, lastSegmentUpdate: now },
        preferences: { trackingConsent: cookies.trackingConsent !== 'false', personalizationEnabled: cookies.personalizationEnabled !== 'false', cookieConsent: true },
      }, undefined, defer);
      return { sessionId, sessionData, isNewSession: true };
    }
    let sessionId = cookies.sessionId || (clientSessionId || '').trim();
    let sessionData: SessionData | null = null;
    let isNewSession = false;

    // Try to get existing session
    if (sessionId) {
      sessionData = await this.sessionManager.getSession(sessionId);
    }

    // Fallback: resolve by stable userId (anon vuid) when the cookie is absent/blocked.
    if (!sessionData) {
      const sid = await this.sessionManager.resolveSessionIdByUserId(userId);
      if (sid) {
        const existing = await this.sessionManager.getSession(sid);
        if (existing) {
          sessionId = sid;
          sessionData = existing;
        }
      }
    }

    // If no valid session, create new one
    if (!sessionData) {
      // CW37. THE ID THE BROWSER ALREADY HOLDS WINS. A cookie naming a session
      // this read could not find is not a reason to mint a second id: KV is
      // eventually consistent, so a record written moments ago can read as
      // absent, and deferring the write off the response path widens that
      // window on purpose. Minting a new id there would split one visit across
      // two sessions, and session-scope attribution compares the decision's
      // session to the outcome's -- a split credits nothing, which is the exact
      // failure found on 2026-09-04. Reusing the id the browser presents costs
      // nothing when it is genuinely new (an id nobody has written is an empty
      // session either way) and keeps the visit whole when it is not.
      sessionId = sessionId || this.sessionManager.generateSessionId();
      isNewSession = true;

      // Get user profile for initial session creation
      const userProfile = await this.getUserProfile(userId);
      sessionData = await this.sessionManager.createOrUpdateSession(sessionId, userId, {
        anonymousId: cookies.anonymousId,
        segments: cookies.segments ? cookies.segments.split(',').filter(Boolean) : userProfile.segments,
        attributes: userProfile.attributes,
        metadata: {
          firstSeen: userProfile.metadata.firstSeen,
          lastSeen: Date.now(),
          sessionCount: userProfile.metadata.sessionCount,
          engagementScore: parseInt(cookies.engagementScore || '0') || calculateEngagementScore(userProfile.attributes),
          lastSegmentUpdate: parseInt(cookies.lastUpdate || '0') || userProfile.lastUpdated
        },
        preferences: {
          // CW31: a cookie the browser has not been given yet says nothing, and nothing means consenting,
          // the same default createOrUpdateSession itself uses. Only an explicit 'false' withholds.
          // Before this, a first visit was stored as having refused both, which nothing honoured until CW31.
          trackingConsent: cookies.trackingConsent !== 'false',
          personalizationEnabled: cookies.personalizationEnabled !== 'false',
          cookieConsent: true
        }
      }, undefined, defer);
    }

    return {
      sessionId: sessionId!,
      sessionData,
      isNewSession
    };
  }

  /**
   * Get personalization configuration for current session
   */
  async getSessionPersonalizationConfig(sessionId: string): Promise<PersonalizationConfig | null> {
    const sessionData = await this.sessionManager.getSession(sessionId);
    if (!sessionData) {
      await this.ensureSeeded();
      return null;
    }
    await this.ensureSeeded(resolveSurface({ surface: sessionData.surface }));

    return this.getPersonalizationConfig(sessionData, sessionId);
  }

  /**
   * Update session preferences
   */
  async updateSessionPreferences(
    sessionId: string,
    preferences: Partial<SessionData['preferences']>
  ): Promise<SessionData | null> {
    return this.sessionManager.updateUserPreferences(sessionId, preferences);
  }

  /**
   * Get session analytics data
   */
  async getSessionAnalytics(sessionId: string): Promise<{
    sessionDuration: number;
    pageViews: number;
    engagementScore: number;
    segmentHistory: string[];
  } | null> {
    return this.sessionManager.getSessionAnalytics(sessionId);
  }

  /**
   * Process action event with session ID from request
   */
  async processActionEventWithSession(
    event: ActionEvent,
    cookieHeader: string | null,
    ctx?: { waitUntil(p: Promise<unknown>): void },
  ): Promise<{
    update: PersonalizationUpdate | null;
    sessionId: string;
    cookieHeaders: string[];
  }> {
    this.keepAlive = ctx ? (p) => { try { ctx.waitUntil(p); } catch { /* no execution context */ } } : undefined;
    const { sessionId } = await this.getOrCreateSessionFromCookies(
      cookieHeader,
      event.userId
    );

    const update = await this.processActionEvent(event, sessionId);

    // Get updated session for cookies
    const updatedSession = await this.sessionManager.getSession(sessionId);
    const cookies = updatedSession ?
      this.sessionManager.generateSessionCookies(updatedSession, sessionId) :
      [];
    const cookieHeaders = this.sessionManager.createCookieHeaders(cookies);

    return {
      update,
      sessionId,
      cookieHeaders
    };
  }

  // Enhanced Feature Variable Management Methods

  /**
   * Get feature variables for a user with enhanced functionality
   */
  async getEnhancedFeatureVariables(
    userId: string,
    userAttributes?: Record<string, any>
  ): Promise<Record<string, FeatureVariableResult>> {
    // Get session data to create enhanced attributes if not provided
    const sessionData = await this.sessionManager.getSessionByUserId(userId);

    if (sessionData && !userAttributes) {
      return this.featureVariableManager.getSessionFeatureVariables(sessionData);
    }

    return this.featureVariableManager.getFeatureVariables(
      userId,
      userAttributes || {}
    );
  }

  /**
   * Set feature variable override for testing/personalization
   */
  async setFeatureVariableOverride(
    userId: string,
    featureKey: string,
    variableKey: string,
    value: any,
    options?: {
      expiresAt?: number;
      reason?: string;
    }
  ): Promise<void> {
    await this.featureVariableManager.setUserOverride({
      userId,
      featureKey,
      variableKey,
      value,
      expiresAt: options?.expiresAt,
      reason: options?.reason
    });

    // Clear any cached personalization configs for this user
    const sessionData = await this.sessionManager.getSessionByUserId(userId);
    if (sessionData) {
      // Trigger a personalization update to reflect the override
      const update: PersonalizationUpdate = {
        type: 'feature_flag_update',
        userId,
        data: {
          featureKey,
          variableKey,
          value,
          source: 'override',
          timestamp: Date.now()
        } as PersonalizationUpdate['data']
      };

      await this.broadcastUpdate(update);
    }
  }

  /**
   * Remove feature variable override
   */
  async removeFeatureVariableOverride(
    userId: string,
    featureKey: string,
    variableKey: string
  ): Promise<void> {
    await this.featureVariableManager.removeUserOverride(userId, featureKey, variableKey);

    // Trigger update to reflect removal
    const sessionData = await this.sessionManager.getSessionByUserId(userId);
    if (sessionData) {
      const update: PersonalizationUpdate = {
        type: 'feature_flag_update',
        userId,
        data: {
          featureKey,
          variableKey,
          source: 'override_removed',
          timestamp: Date.now()
        } as PersonalizationUpdate['data']
      };

      await this.broadcastUpdate(update);
    }
  }

  /**
   * Get all feature variable overrides for a user
   */
  async getUserFeatureVariableOverrides(userId: string) {
    return this.featureVariableManager.getUserOverrides(userId);
  }

  /**
   * Get feature variable configurations for demo/testing
   */
  getFeatureVariableConfigurations() {
    return this.featureVariableManager.getFeatureConfigurations();
  }

  /**
   * Create demo feature variable overrides for testing
   */
  async createDemoFeatureVariableOverrides(userId: string): Promise<void> {
    await this.featureVariableManager.createDemoOverrides(userId);

    // Broadcast update about demo overrides
    const update: PersonalizationUpdate = {
      type: 'feature_flag_update',
      userId,
      data: {
        source: 'demo_overrides_created',
        timestamp: Date.now()
      }
    };

    await this.broadcastUpdate(update);
  }

  /**
   * Get feature variable analytics
   */
  async getFeatureVariableAnalytics() {
    return this.featureVariableManager.getFeatureVariableAnalytics();
  }
}

import type { Env } from '@/types/env';
import type { ReflexChanges, ReflexConfig, ReflexState } from '@/reflex/core';
import { mergeReflexStates } from '@/reflex/identityMerge';
import { z } from 'zod';
import { assertSessionTarget, SessionAccessError, type SessionCapability } from '@/identity/sessionCapability';
import { consentOf, intersectConsent, type Consent } from '@/content/consent';

import {
  classifyEntryChannel, isNewVisit, nextVisitCount,
  type ChannelSignals, type EntryChannel,
} from '@/services/visit';
import { DEFAULT_TENANT, TenantKV, type KVLike, type TenantId } from '@/tenancy/tenant';

export interface SessionData {
  userId: string;
  anonymousId?: string;
  segments: string[];
  attributes: Record<string, any>;
  /** Demo surface this session belongs to (@/demos/registry). ABSENT ⇒ 'coach' —
      every session written before the multi-surface split is the retail demo's. */
  surface?: string;
  /** Edge Affinity Reflex state (doc 16) — raw (R, tLast) per dimension·value.
      P0 hosting: rides the session; relocates into the ShopperReflex DO in P2. */
  reflex?: ReflexState;
  /** ODP loop (doc 16 §8): the session's last-seeded qualified ODP audiences + when. */
  odpSeed?: string[];
  odpSeedAt?: number;
  /** Ring of the session's recent events in the FLAT recent_events shape (≤10, ≤55min)
      — injected inline into the GraphQL read for instant (~200ms) qualification. */
  odpRecentEvents?: Array<Record<string, unknown>>;
  /**
   * CW25. Set on a record whose visitor was linked to a person: reads and
   * writes addressed to this session land on the person's session instead. The
   * record keeps its old content underneath, so if the target ever expires the
   * browser still has what it had. One hop, never chained.
   */
  forwardTo?: string;
  /**
   * CW25. Present on the PERSON's session. Its userId is the shopper id, and a
   * write arriving with a browser's visitor id must not overwrite it, or the
   * ODP vuid and the identity anchor would flap between devices.
   */
  identity?: { shopperId: string; linkedAt: number };
  metadata: {
    firstSeen: number;
    lastSeen: number;
    /**
     * Interactions, NOT visits. It increments on every createOrUpdateSession
     * call, which is what it has always done; the name is misleading and the
     * field is kept because it is persisted and read. For "how many times has
     * this shopper been here", use visitCount.
     */
    sessionCount: number;
    /**
     * Visits, counted on an idle-gap boundary (see @/services/visit). Optional
     * because records written before this field existed must still parse:
     * getSession() runs the schema and swallows a failure as null, so a required
     * field here would silently wipe every live session on deploy.
     */
    visitCount?: number;
    /** When the current visit began. */
    lastVisitAt?: number;
    /** How this visit was entered. Classified once per visit, then carried. */
    entryChannel?: EntryChannel;
    engagementScore: number;
    lastSegmentUpdate: number;
    journeyStage?: 'early' | 'mid' | 'late';
  };
  preferences: {
    trackingConsent: boolean;
    personalizationEnabled: boolean;
    cookieConsent: boolean;
  };
}

export interface CookieConfig {
  name: string;
  value: string;
  maxAge?: number;
  httpOnly?: boolean;
  secure?: boolean;
  sameSite?: 'Strict' | 'Lax' | 'None';
  domain?: string;
  path?: string;
}

export interface SessionCookies {
  sessionId: string;
  segments: string;
  userId?: string;
  anonymousId?: string;
  engagementScore: string;
  lastUpdate: string;
  trackingConsent: string;
  personalizationEnabled: string;
}

const sessionDataSchema = z.object({
  userId: z.string(),
  anonymousId: z.string().optional(),
  segments: z.array(z.string()),
  attributes: z.record(z.string(), z.any()),
  // Declared or .parse() silently STRIPS it on every read/write (same trap as reflex).
  surface: z.string().optional(),
  // Reflex state must be declared or .parse() silently STRIPS it on every read/write.
  reflex: z.any().optional(),
  odpSeed: z.array(z.string()).optional(),
  odpSeedAt: z.number().optional(),
  odpRecentEvents: z.array(z.any()).optional(),
  // CW25. Declared or .parse() silently STRIPS them, same trap as reflex.
  forwardTo: z.string().optional(),
  identity: z.object({ shopperId: z.string(), linkedAt: z.number() }).optional(),
  metadata: z.object({
    firstSeen: z.number(),
    lastSeen: z.number(),
    sessionCount: z.number(),
    // Optional, deliberately: see the note on the interface above. A required
    // field would fail .parse() on every record written before this deploy, and
    // getSession() turns a parse failure into null.
    visitCount: z.number().optional(),
    lastVisitAt: z.number().optional(),
    // An enum, so the parsed type matches the interface, with .catch so an
    // unrecognised stored value degrades to undefined instead of failing the
    // parse and taking the whole session with it.
    entryChannel: z
      .enum(['direct', 'paid_social', 'paid_search', 'email', 'organic', 'referral'])
      .optional()
      .catch(undefined),
    engagementScore: z.number(),
    lastSegmentUpdate: z.number(),
    journeyStage: z.enum(['early', 'mid', 'late']).optional()
  }),
  preferences: z.object({
    trackingConsent: z.boolean(),
    personalizationEnabled: z.boolean(),
    cookieConsent: z.boolean()
  })
});

/**
 * CW25. Attributes that count events, which add across a person's devices. The
 * names are RETAIL_SIGNAL_DEFAULTS' (RealtimeSegmentEngine); anything not here
 * is a latest-value attribute, on which the person's record wins.
 */
/** How often a forwarding record has its TTL renewed under a browser that keeps using it. */
const FORWARD_REFRESH_MS = 24 * 60 * 60 * 1000;

const COUNTER_ATTRIBUTES = new Set(['product_views', 'cart_adds', 'wishlist_adds', 'page_views', 'category_dwell_ms', 'purchases']);

export class SessionManager {
  private env: Env;
  readonly tenant: TenantId;
  private sessionTTL: number = 30 * 24 * 60 * 60; // 30 days in seconds
  private cookieDomain: string;
  private isSecure: boolean;

  /**
   * Sessions scoped to one brand (CW1). A visitor on Kate Spade and a visitor on
   * Coach who happen to share a session id are two different people, and without
   * this they were one: `session:{id}` was a global key.
   *
   * The default tenant is unprefixed, so an existing `new SessionManager(env)`
   * reads and writes exactly the keys it always did and no live session moves.
   */
  private readonly kv: KVLike;

  readonly principal?: SessionCapability;

  constructor(env: Env, options?: { domain?: string; secure?: boolean; tenant?: TenantId; principal?: SessionCapability }) {
    this.env = env;
    this.tenant = options?.tenant ?? DEFAULT_TENANT;
    this.principal = options?.principal;
    if (this.principal && this.principal.tenant !== this.tenant) throw new SessionAccessError();
    this.kv = new TenantKV(env.SESSIONS as unknown as KVLike, this.tenant);
    this.cookieDomain = options?.domain || '';
    this.isSecure = options?.secure ?? true;
  }

  /**
   * Create a new session or update existing one
   */
  async createOrUpdateSession(
    sessionId: string,
    userId: string,
    data: Partial<SessionData>,
    /**
     * How this request arrived: utm tags and referrer. Only consulted when this
     * call opens a new visit, because entry is a property of the visit and not
     * of every event inside it. Optional, so no existing call site changes.
     */
    entry?: ChannelSignals,
    /**
     * CW37. Where the KV writes go instead of being awaited. A decision does not
     * depend on the session having been STORED -- it is computed from the record
     * this call returns -- and a KV write costs half a second or more from a
     * Worker, which doc 32 measured as the whole of a new shopper's 627 ms. Hand
     * this a sink (the request's `waitUntil`) and the write leaves the response
     * path. Omit it and nothing changes: every existing caller still awaits.
     */
    defer?: (p: Promise<unknown>) => void,
  ): Promise<SessionData> {
    if (this.principal) {
      assertSessionTarget(this.principal, userId, sessionId);
      if (data.forwardTo || (data.identity && (this.principal.kind !== 'recognized' || data.identity.shopperId !== userId))) throw new SessionAccessError();
    }
    try {
      // CW25. A browser that was linked to a person writes to the person's
      // session; the id on the cookie stays what it was, the record it names
      // forwards. Resolved once here, for the read below and the write at the end.
      const target = await this.resolveRecord(sessionId);
      sessionId = target.id;
      const existingSession = target.data;
      // A person's session keeps the person's id whatever browser is writing.
      if (existingSession?.identity && existingSession.userId !== userId) userId = existingSession.userId;

      const now = Date.now();

      // THE VISIT BOUNDARY. Read lastSeen from the STORED record, never from the
      // incoming data: a caller that passes `metadata.lastSeen: Date.now()` would
      // otherwise close the gap it is being measured against, and every event
      // would look like a new visit.
      const priorLastSeen = existingSession?.metadata.lastSeen;
      const openingNewVisit = isNewVisit(priorLastSeen, now);
      const visitCount = nextVisitCount(existingSession?.metadata.visitCount, priorLastSeen, now);
      // A record written before visitCount existed resolves to visit 1. That
      // under-counts a returning shopper once, which is honest; seeding from
      // sessionCount would import its wrongness instead.
      const entryChannel: EntryChannel = openingNewVisit && entry
        ? classifyEntryChannel(entry)
        : (existingSession?.metadata.entryChannel ?? (entry ? classifyEntryChannel(entry) : 'direct'));

      const sessionData: SessionData = {
        userId,
        anonymousId: data.anonymousId || existingSession?.anonymousId,
        segments: data.segments || existingSession?.segments || ['new_user'],
        attributes: {
          ...existingSession?.attributes,
          ...data.attributes
        },
        surface: data.surface ?? existingSession?.surface,
        reflex: data.reflex ?? existingSession?.reflex,
        odpSeed: data.odpSeed ?? existingSession?.odpSeed,
        odpSeedAt: data.odpSeedAt ?? existingSession?.odpSeedAt,
        odpRecentEvents: data.odpRecentEvents ?? existingSession?.odpRecentEvents,
        identity: data.identity ?? existingSession?.identity,
        metadata: {
          firstSeen: existingSession?.metadata.firstSeen || now,
          lastSeen: now,
          sessionCount: existingSession ? existingSession.metadata.sessionCount + 1 : 1,
          visitCount,
          lastVisitAt: openingNewVisit ? now : (existingSession?.metadata.lastVisitAt ?? now),
          entryChannel,
          engagementScore: data.metadata?.engagementScore || existingSession?.metadata.engagementScore || 0,
          lastSegmentUpdate: data.segments ? now : existingSession?.metadata.lastSegmentUpdate || now,
          journeyStage: data.metadata?.journeyStage ?? existingSession?.metadata.journeyStage
        },
        preferences: {
          trackingConsent: data.preferences?.trackingConsent ?? existingSession?.preferences.trackingConsent ?? true,
          personalizationEnabled: data.preferences?.personalizationEnabled ?? existingSession?.preferences.personalizationEnabled ?? true,
          cookieConsent: data.preferences?.cookieConsent ?? existingSession?.preferences.cookieConsent ?? true
        }
      };

      // Validate the session data
      const validatedData = sessionDataSchema.parse(sessionData);

      // CW31 (BTIE D10). A shopper who withheld tracking consent is still
      // ANSWERED, from the state that is already stored, and nothing this
      // request learned is kept. This is the object host's rule exactly
      // (ShopperReflex step 8, where the record is restored to what it was):
      // the two hosts must never disagree about the same shopper, because
      // REFLEX_HOST decides which one a brand runs on and consent is not a
      // property of that choice.
      //
      // The one write that still happens is the INSTRUCTION itself. Without it
      // the next request reads no stored preference, the default of that is
      // consenting, and the engine would start writing again on the request
      // after the shopper asked it to stop.
      if (!validatedData.preferences.trackingConsent) {
        const onlyTheInstruction = sessionDataSchema.parse(
          existingSession
            ? { ...existingSession, preferences: validatedData.preferences }
            : {
                userId,
                segments: [],
                attributes: {},
                metadata: { firstSeen: now, lastSeen: now, sessionCount: 0, engagementScore: 0, lastSegmentUpdate: now },
                preferences: validatedData.preferences,
              }
        );
        // The pointer stays, or the switches could not be found again.
        const refusal = Promise.all([
          this.kv.put(`session:${sessionId}`, JSON.stringify(onlyTheInstruction), { expirationTtl: this.sessionTTL }),
          this.kv.put(`user:${userId}`, sessionId, { expirationTtl: this.sessionTTL }),
        ]);
        if (defer) defer(refusal); else await refusal;
        return validatedData;
      }

      // The record, and the pointer that finds it by user id. These were two
      // awaits in sequence, which paid for two round trips where one would do;
      // neither depends on the other.
      const writes = Promise.all([
        this.kv.put(`session:${sessionId}`, JSON.stringify(validatedData), { expirationTtl: this.sessionTTL }),
        this.kv.put(`user:${userId}`, sessionId, { expirationTtl: this.sessionTTL }),
      ]);
      if (defer) defer(writes); else await writes;

      return validatedData;

    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error creating/updating session');
      throw error;
    }
  }

  /** The record exactly as stored, forward and all. */
  async readRaw(sessionId: string, strict = false): Promise<SessionData | null> {
    if (this.principal) assertSessionTarget(this.principal, undefined, sessionId);
    let raw: SessionData | null;
    try {
      const stored = await this.kv.get(`session:${sessionId}`, strict ? undefined : 'json');
      const sessionData = strict && stored !== null && typeof stored === 'string' ? JSON.parse(stored) : stored;
      raw = strict ? (stored === null ? null : sessionDataSchema.parse(sessionData)) : (sessionData ? sessionDataSchema.parse(sessionData) : null);
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      if (this.principal || strict) throw new SessionAccessError();
      console.error('Error retrieving session');
      return null;
    }
    if (this.principal) {
      assertSessionTarget(this.principal);
      if (raw ? raw.userId !== this.principal.subject || !!raw.forwardTo
        || (this.principal.kind === 'anonymous' ? !!raw.identity : raw.identity?.shopperId !== this.principal.subject)
        : this.principal.kind === 'recognized') throw new SessionAccessError();
    }
    return raw;
  }

  /**
   * The session a request for `sessionId` actually lands on: the record itself,
   * or the person's session it forwards to. One hop. If the target has expired
   * the browser's own record is returned, which is what it had before the link.
   */
  async resolveRecord(sessionId: string): Promise<{ id: string; data: SessionData | null }> {
    const raw = await this.readRaw(sessionId);
    if (this.principal) return { id: sessionId, data: raw };
    if (raw?.forwardTo && raw.forwardTo !== sessionId) {
      const target = await this.readRaw(raw.forwardTo);
      if (target) {
        // The browser's record and its `user:` pointer are never rewritten by
        // the writes that now land on the person, so they would expire under a
        // browser that kept coming back. Refreshed once a day, off the hot path.
        const now = Date.now();
        if (now - raw.metadata.lastSeen > FORWARD_REFRESH_MS) {
          const refreshed = { ...raw, metadata: { ...raw.metadata, lastSeen: now } };
          await Promise.all([
            this.kv.put(`session:${sessionId}`, JSON.stringify(refreshed), { expirationTtl: this.sessionTTL }),
            this.kv.put(`user:${raw.userId}`, raw.forwardTo, { expirationTtl: this.sessionTTL }),
          ]);
        }
        return { id: raw.forwardTo, data: target };
      }
    }
    return { id: sessionId, data: raw };
  }

  /**
   * Get session data by session ID. Follows a link (CW25), so a browser that
   * was recognised reads the person's profile from its old cookie.
   */
  async getSession(sessionId: string): Promise<SessionData | null> {
    return (await this.resolveRecord(sessionId)).data;
  }

  /** Necessary refusal storage only: no visit, profile merge, or user-pointer write. */
  async restrictConsent(sessionId: string, hints: Consent): Promise<Consent> {
    const previous = await this.readRaw(sessionId, true);
    const consent = intersectConsent(consentOf(previous), hints);
    if (consent.tracking && consent.personalization) return consent;
    if (previous && previous.preferences.trackingConsent === consent.tracking
      && previous.preferences.personalizationEnabled === consent.personalization) return consent;
    if (!previous && !this.principal) throw new SessionAccessError();
    const now = Date.now();
    const data: SessionData = {
      ...(previous ?? {
        userId: this.principal!.subject, segments: [], attributes: {},
        metadata: { firstSeen: now, lastSeen: now, sessionCount: 0, engagementScore: 0, lastSegmentUpdate: now },
      }),
      preferences: { trackingConsent: consent.tracking, personalizationEnabled: consent.personalization, cookieConsent: previous?.preferences.cookieConsent ?? true },
    };
    await this.kv.put(`session:${sessionId}`, JSON.stringify(sessionDataSchema.parse(data)), { expirationTtl: this.sessionTTL });
    return consent;
  }

  /**
   * CW25. Fold a browser's session into a person's, and leave the browser's
   * record forwarding there.
   *
   * The person's session is `user:{shopperId}`'s, created here on the first
   * link. The reflex vectors merge on the decay invariant (identityMerge.ts);
   * visits add, because two devices' visits are one person's visits; first seen
   * is the earliest, last seen the latest, the counters sum, and on anything
   * else the person's existing record wins over the browser's. Segments are
   * unioned and the reflex memberships re-evaluated, so the returned changes
   * are exactly what the link did to this person's audiences.
   */
  async absorbIntoShopper(input: {
    shopperId: string;
    /** The browser being linked. Its `user:` key is pointed at the person even when it had no session yet. */
    visitorId?: string;
    from: SessionData | null;
    fromSessionId: string | null;
    config: ReflexConfig;
    now?: number;
    /**
     * `merge` folds the browser's profile in (a first link). `repoint` only moves
     * the browser: it was linked to someone else before, its profile already
     * went there, and a shared computer's second account must not inherit it.
     */
    mode?: 'merge' | 'repoint';
    /** Public identity transitions intersect, never upgrade, the source switches. */
    consent?: Consent;
  }): Promise<{ sessionId: string; data: SessionData; changes: ReflexChanges; created: boolean }> {
    const now = input.now ?? Date.now();
    const { shopperId } = input;
    const browserId = input.visitorId ?? input.from?.userId;
    // THE GUARD. Only a browser's own record is ever folded or forwarded: one
    // that carries no identity and is named by the browser being linked. A
    // person's session handed in here by mistake (the `user:` key of a linked
    // browser points at the person, not the browser) must never be forwarded to
    // another person, which would hand one shopper's profile to another.
    const from = input.from && !input.from.identity && input.from.userId === browserId ? input.from : null;

    let canonicalId = (await this.kv.get(`user:${shopperId}`)) as string | null;
    let base: SessionData | null = canonicalId ? await this.readRaw(canonicalId, input.consent !== undefined) : null;
    const created = !base;
    if (!base) canonicalId = this.generateSessionId();
    // A browser already forwarding here, or one being repointed, has nothing to fold in.
    const fold = input.mode !== 'repoint' && from && from.forwardTo !== canonicalId && from.userId !== shopperId ? from : null;

    const merged = mergeReflexStates(base?.reflex, fold?.reflex, now, input.config);
    const counters: Record<string, unknown> = { ...(fold?.attributes ?? {}), ...(base?.attributes ?? {}) };
    for (const k of Object.keys(fold?.attributes ?? {})) {
      const a = base?.attributes?.[k]; const b = fold?.attributes?.[k];
      if (typeof a === 'number' && typeof b === 'number' && COUNTER_ATTRIBUTES.has(k)) counters[k] = a + b;
    }
    const laterVisit = (fold?.metadata.lastVisitAt ?? 0) > (base?.metadata.lastVisitAt ?? 0) ? fold : base;

    const data: SessionData = {
      userId: shopperId,
      anonymousId: base?.anonymousId ?? fold?.anonymousId,
      segments: [...new Set([...(base?.segments ?? []), ...(fold?.segments ?? []), ...merged.state.audiences])].sort(),
      attributes: counters,
      surface: base?.surface ?? fold?.surface,
      reflex: merged.state,
      odpSeed: base?.odpSeed ?? fold?.odpSeed,
      odpSeedAt: base?.odpSeedAt ?? fold?.odpSeedAt,
      odpRecentEvents: [...(fold?.odpRecentEvents ?? []), ...(base?.odpRecentEvents ?? [])].slice(-10),
      identity: base?.identity ?? { shopperId, linkedAt: now },
      metadata: {
        firstSeen: Math.min(base?.metadata.firstSeen ?? now, fold?.metadata.firstSeen ?? now),
        lastSeen: Math.max(base?.metadata.lastSeen ?? 0, fold?.metadata.lastSeen ?? 0) || now,
        sessionCount: (base?.metadata.sessionCount ?? 0) + (fold?.metadata.sessionCount ?? 0),
        visitCount: (base?.metadata.visitCount ?? 0) + (fold?.metadata.visitCount ?? 0) || undefined,
        lastVisitAt: laterVisit?.metadata.lastVisitAt,
        entryChannel: laterVisit?.metadata.entryChannel,
        engagementScore: Math.max(base?.metadata.engagementScore ?? 0, fold?.metadata.engagementScore ?? 0),
        lastSegmentUpdate: now,
        journeyStage: base?.metadata.journeyStage ?? fold?.metadata.journeyStage,
      },
      preferences: base?.preferences ?? fold?.preferences ?? { trackingConsent: true, personalizationEnabled: true, cookieConsent: true },
    };
    if (input.consent) {
      const consent = intersectConsent(consentOf(data), input.consent);
      data.preferences = { ...data.preferences, trackingConsent: consent.tracking, personalizationEnabled: consent.personalization };
    }
    const validated = sessionDataSchema.parse(data);

    await this.kv.put(`session:${canonicalId}`, JSON.stringify(validated), { expirationTtl: this.sessionTTL });
    await this.kv.put(`user:${shopperId}`, canonicalId!, { expirationTtl: this.sessionTTL });
    if (browserId && browserId !== shopperId) {
      await this.kv.put(`user:${browserId}`, canonicalId!, { expirationTtl: this.sessionTTL });
    }
    if (from) {
      if (input.fromSessionId && input.fromSessionId !== canonicalId) {
        // The browser's record stays as it was, plus the pointer: roll forward, never rewind.
        const tomb = sessionDataSchema.parse({ ...from, forwardTo: canonicalId });
        await this.kv.put(`session:${input.fromSessionId}`, JSON.stringify(tomb), { expirationTtl: this.sessionTTL });
      }
    }
    return { sessionId: canonicalId!, data: validated, changes: merged.changes, created };
  }

  /**
   * CW25. Write an imported reflex vector onto a shopper's session, and nothing
   * else about the visit. History informs interest; it does not claim visits the
   * engine never saw, so lastSeen and the visit number are left exactly as they
   * were. A shopper met first through an import gets a record with the identity
   * block and no visit at all.
   */
  async applyImport(input: {
    userId: string;
    reflex: ReflexState;
    identity?: { shopperId: string; linkedAt: number };
    now?: number;
  }): Promise<{ sessionId: string; data: SessionData; created: boolean }> {
    const now = input.now ?? Date.now();
    const sid0 = (await this.kv.get(`user:${input.userId}`)) as string | null;
    const resolved = sid0 ? await this.resolveRecord(sid0) : { id: this.generateSessionId(), data: null };
    const existing = resolved.data;
    const sessionId = resolved.id;
    const data: SessionData = existing
      ? {
          ...existing,
          reflex: input.reflex,
          segments: [...new Set([...existing.segments, ...input.reflex.audiences])].sort(),
          identity: existing.identity ?? input.identity,
          metadata: { ...existing.metadata, lastSegmentUpdate: now },
        }
      : {
          userId: input.userId,
          segments: [...input.reflex.audiences].sort(),
          attributes: {},
          reflex: input.reflex,
          identity: input.identity,
          metadata: { firstSeen: now, lastSeen: 0, sessionCount: 0, engagementScore: 0, lastSegmentUpdate: now },
          preferences: { trackingConsent: true, personalizationEnabled: true, cookieConsent: true },
        };
    const validated = sessionDataSchema.parse(data);
    await this.kv.put(`session:${sessionId}`, JSON.stringify(validated), { expirationTtl: this.sessionTTL });
    await this.kv.put(`user:${validated.userId}`, sessionId, { expirationTtl: this.sessionTTL });
    return { sessionId, data: validated, created: !existing };
  }

  /**
   * CW28. Forget a browser entirely: its `user:` pointer, and its own record
   * when the link remembered one (after a link the pointer names the person, so
   * the browser's pre-link record is reachable only this way).
   */
  async forgetVisitor(userId: string, ownSessionId?: string | null): Promise<void> {
    try {
      if (ownSessionId) await this.kv.delete(`session:${ownSessionId}`);
      await this.kv.delete(`user:${userId}`);
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error forgetting visitor');
    }
  }

  /**
   * Get session data by user ID
   */
  async getSessionByUserId(userId: string): Promise<SessionData | null> {
    if (this.principal) {
      assertSessionTarget(this.principal, userId);
      return this.getSession(this.principal.sessionId);
    }
    try {
      const sessionId = (await this.kv.get(`user:${userId}`)) as string | null;
      if (!sessionId) {
        return null;
      }

      return this.getSession(sessionId);
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error retrieving session by user ID');
      return null;
    }
  }

  /**
   * Resolve the current sessionId for a stable userId (anon vuid), if any.
   * Used as a continuity fallback when the session cookie is absent or blocked.
   */
  async resolveSessionIdByUserId(userId: string): Promise<string | null> {
    if (this.principal) {
      assertSessionTarget(this.principal, userId);
      return this.principal.sessionId;
    }
    try {
      return (await this.kv.get(`user:${userId}`)) as string | null;
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error resolving session id by user ID');
      return null;
    }
  }

  /**
   * Update user segments in session
   */
  async updateUserSegments(
    sessionId: string,
    segments: string[],
    engagementScore?: number
  ): Promise<SessionData | null> {
    try {
      const existingSession = await this.getSession(sessionId);
      if (!existingSession) {
        return null;
      }

      const updatedSession = await this.createOrUpdateSession(sessionId, existingSession.userId, {
        ...existingSession,
        segments,
        metadata: {
          ...existingSession.metadata,
          engagementScore: engagementScore ?? existingSession.metadata.engagementScore,
          lastSegmentUpdate: Date.now()
        }
      });

      return updatedSession;
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error updating user segments');
      return null;
    }
  }

  /**
   * Generate secure cookies for client-side persistence
   */
  generateSessionCookies(sessionData: SessionData, sessionId: string): CookieConfig[] {
    const cookieOptions: Partial<CookieConfig> = {
      maxAge: this.sessionTTL,
      httpOnly: false, // Need to be accessible to JavaScript for personalization
      secure: this.isSecure,
      sameSite: 'Lax',
      path: '/',
      ...(this.cookieDomain && { domain: this.cookieDomain })
    };

    const cookies: CookieConfig[] = [
      {
        name: 'opt_session_id',
        value: sessionId,
        ...cookieOptions,
        httpOnly: true // Session ID should be HTTP-only for security
      },
      {
        name: 'opt_user_id',
        value: sessionData.userId,
        ...cookieOptions
      },
      {
        name: 'opt_segments',
        value: sessionData.segments.join(','),
        ...cookieOptions
      },
      {
        name: 'opt_engagement_score',
        value: sessionData.metadata.engagementScore.toString(),
        ...cookieOptions
      },
      {
        name: 'opt_last_update',
        value: sessionData.metadata.lastSegmentUpdate.toString(),
        ...cookieOptions
      },
      {
        name: 'opt_tracking_consent',
        value: sessionData.preferences.trackingConsent.toString(),
        ...cookieOptions
      },
      {
        name: 'opt_personalization_enabled',
        value: sessionData.preferences.personalizationEnabled.toString(),
        ...cookieOptions
      }
    ];

    // Add anonymous ID cookie if available
    if (sessionData.anonymousId) {
      cookies.push({
        name: 'opt_anonymous_id',
        value: sessionData.anonymousId,
        ...cookieOptions
      });
    }

    return cookies;
  }

  /**
   * Parse session cookies from request headers
   */
  parseSessionCookies(cookieHeader: string | null): Partial<SessionCookies> {
    if (!cookieHeader) {
      return {};
    }

    const cookies: Record<string, string> = {};

    cookieHeader.split(';').forEach(cookie => {
      const [name, ...value] = cookie.trim().split('=');
      if (name && value.length > 0) {
        cookies[name] = decodeURIComponent(value.join('='));
      }
    });

    return {
      sessionId: cookies['opt_session_id'],
      userId: cookies['opt_user_id'],
      anonymousId: cookies['opt_anonymous_id'],
      segments: cookies['opt_segments'],
      engagementScore: cookies['opt_engagement_score'],
      lastUpdate: cookies['opt_last_update'],
      trackingConsent: cookies['opt_tracking_consent'],
      personalizationEnabled: cookies['opt_personalization_enabled']
    };
  }

  /**
   * Create cookie header string for HTTP response
   */
  /**
   * Private identity/profile mirrors only. Refusal cookies must survive logout/reset.
   * `maxAge` 0 is rendered by hand because createCookieHeaders treats 0 as unset.
   */
  clearCookieHeaders(): string[] {
    const names = ['opt_session_id', 'opt_user_id', 'opt_anonymous_id', 'opt_segments',
      'opt_engagement_score', 'opt_last_update'];
    const domain = this.cookieDomain ? `; Domain=${this.cookieDomain}` : '';
    return names.map((n) => `${n}=; Max-Age=0; Path=/${domain}; SameSite=Lax`);
  }

  createCookieHeaders(cookies: CookieConfig[]): string[] {
    return cookies.map(cookie => {
      let header = `${cookie.name}=${encodeURIComponent(cookie.value)}`;

      if (cookie.maxAge) {
        header += `; Max-Age=${cookie.maxAge}`;
      }

      if (cookie.domain) {
        header += `; Domain=${cookie.domain}`;
      }

      if (cookie.path) {
        header += `; Path=${cookie.path}`;
      }

      if (cookie.secure) {
        header += '; Secure';
      }

      if (cookie.httpOnly) {
        header += '; HttpOnly';
      }

      if (cookie.sameSite) {
        header += `; SameSite=${cookie.sameSite}`;
      }

      return header;
    });
  }

  /**
   * Generate a new session ID
   */
  generateSessionId(): string {
    return crypto.randomUUID();
  }

  /**
   * Delete session and clear cookies
   */
  async deleteSession(sessionId: string): Promise<boolean> {
    if (this.principal) assertSessionTarget(this.principal, undefined, sessionId);
    try {
      // The record as stored, NOT what it forwards to: deleting a linked
      // browser's session detaches that browser; only the person's own session
      // id erases the person.
      const sessionData = await this.readRaw(sessionId);

      // Delete session data
      await this.kv.delete(`session:${sessionId}`);

      // Delete user ID mapping
      if (sessionData) {
        await this.kv.delete(`user:${sessionData.userId}`);
      }

      return true;
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error deleting session');
      return false;
    }
  }

  /**
   * Clear expired sessions (to be called by scheduled worker)
   */
  async cleanupExpiredSessions(): Promise<number> {
    try {
      // KV automatically handles TTL expiration, but we can manually clean up if needed
      // This is more for logging/metrics purposes
      console.log('Session cleanup scheduled - KV TTL handles automatic expiration');
      return 0;
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error during session cleanup');
      return 0;
    }
  }

  /**
   * Get session analytics data
   */
  async getSessionAnalytics(sessionId: string): Promise<{
    sessionDuration: number;
    pageViews: number;
    engagementScore: number;
    segmentHistory: string[];
  } | null> {
    try {
      const sessionData = await this.getSession(sessionId);
      if (!sessionData) {
        return null;
      }

      const sessionDuration = Date.now() - sessionData.metadata.firstSeen;

      return {
        sessionDuration,
        pageViews: sessionData.attributes.page_views || 0,
        engagementScore: sessionData.metadata.engagementScore,
        segmentHistory: sessionData.segments
      };
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error retrieving session analytics');
      return null;
    }
  }

  /**
   * Update user preferences
   */
  async updateUserPreferences(
    sessionId: string,
    preferences: Partial<SessionData['preferences']>
  ): Promise<SessionData | null> {
    try {
      const existingSession = await this.getSession(sessionId);
      if (!existingSession) {
        return null;
      }

      return this.createOrUpdateSession(sessionId, existingSession.userId, {
        ...existingSession,
        preferences: {
          ...existingSession.preferences,
          ...preferences
        }
      });
    } catch (error) {
      if (error instanceof SessionAccessError) throw error;
      console.error('Error updating user preferences');
      return null;
    }
  }
}

// src/durable-objects/ShopperReflex.ts
// ─────────────────────────────────────────────────────────────────────────────
// ShopperReflex — the per-shopper hot Durable Object (doc 16 §6, P2).
//
// A SQLite-backed DO (wrangler migration v4, `new_sqlite_classes`) that owns BOTH
// the WebSocket and the affinity state, so state and compute are co-located and
// hot: event → decay+add → evaluate audiences → changed? → push, all inside one
// object, no KV session round-trip, no cross-object hop on the push.
//
//   • One object per shopper, keyed on the STABLE visitor id
//     (SHOPPER_REFLEX.idFromName(opt_visitor_id)) — every tab/device carrying the
//     same id lands on the same object and receives the same pushes.
//   • WebSocket Hibernation API (`state.acceptWebSocket` / `webSocketMessage`):
//     objects park at near-zero cost between events and survive eviction. The
//     socket attachment carries ONLY `{shopperId}` — the ~2KB attachment cap is a
//     hard rule; ALL state lives in `ctx.storage` and rehydrates on wake.
//   • Two ingest doors, ONE handler: `webSocketMessage` (`{type:'action', …}`
//     frames) and `fetch POST /ingest` (no-WS clients, sendBeacon on unload, and
//     the existing POST /realtime/action which forwards here when
//     REFLEX_HOST='do'). Both call the same `ingest(event)`; the DO stamps
//     `Date.now()` on arrival — client timestamps are advisory only (§4).
//   • Closed-form alarms: core's `nextCrossing()` solves the exact instant the
//     earliest current membership decays below θ_out; `alarm()` re-evaluates
//     lazily (decay is read-time math — the alarm never mutates scores), pushes
//     the exits, and schedules the next crossing. No polling, exact-time exits.
//   • Retention lifecycle (§12): an object idle past REFLEX_RETENTION_DAYS
//     (default 30) self-expires via `ctx.storage.deleteAll()`.
//
// ENGINE REUSE, NOT REIMPLEMENTATION — the design decision, recorded:
// RealtimeSegmentEngine is session-coupled by construction (SessionManager/KV
// sessions, cookie headers, and a broadcast that hops to the relay DO), so it is
// NOT instantiated in here. Instead this DO hosts a THIN pipeline that calls the
// SAME modules the request path calls — zero math or policy is copied:
//   ReflexCore (@/reflex/core)      → apply/tick/snapshot/attributesFrom/nextCrossing
//   attribute accrual + engagement  → applyEventToAttributes / calculateEngagementScore
//                                     (exported verbatim from RealtimeSegmentEngine)
//   qualification                   → getConnectors(env).segments — KvAudienceStore +
//                                     evaluateCondition via MockSegmentProvider,
//                                     seeded by the shared ensureAudiencesSeeded
//   journey stage                   → deriveStage (@/services/JourneyStage)
//   ODP loop                        → updateOdpRing / refreshOdpSeedIfDue /
//                                     forwardEventToOdp / upsertOdpProfile (@/services/odpLoop)
//   decisions                       → getConnectors(env).decisions.decideAll over
//                                     CATALOG_FLAG_KEYS (Mock or Live per DECISION_SOURCE)
//
// Identity note: the ODP vuid remains SESSION-derived (SHA-256 of the DO-held
// sessionId, minted once per shopper object) until the identity cutover maps
// vuid ⇄ stable shopperId (doc 16 §8). "New shopper" rotates the client's
// visitor id → a fresh object → a fresh sessionId → a fresh vuid.
// ─────────────────────────────────────────────────────────────────────────────

