      [`/realtime/segments/${victim.subject}`], [`/realtime/segments/${victim.subject}`, { segment: 'private' }], [`/realtime/connections/${victim.subject}`],
      [`/v1/meridian/decisions/snapshot?visitorId=${victim.subject}&userId=${grant.subject}`],
